package com.bank.jvm;

import java.util.concurrent.*;
import java.util.logging.*;

// Shows quick tasks starving in a tiny pool, then a fixed, fairly-sized setup.
public class StarvationDemo {
    private static final Logger log = Logger.getLogger(StarvationDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // --- STARVATION: tiny pool, slow tasks hog all threads ---
        ThreadPoolExecutor tiny = new ThreadPoolExecutor(
                2, 2, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        PoolInspector inspector = new PoolInspector();

        for (int i = 0; i < 20; i++) tiny.submit(new TransferTask("TXF-" + i)); // slow, fills pool
        long submitted = System.currentTimeMillis();
        Future<Long> check = tiny.submit(new BalanceCheckTask("SAV2001")); // quick but STARVED
        inspector.report("tiny pool", tiny);
        long waitedMs = check.get() + (System.currentTimeMillis() - submitted);
        log.warning("STARVED: quick balance check waited ~" + waitedMs + "ms behind slow transfers");
        tiny.shutdownNow();

        // --- FIX: right-sized pool + separate fast lane for quick tasks ---
        ThreadPoolExecutor slowLane = new ThreadPoolExecutor(
                8, 8, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        ThreadPoolExecutor fastLane = new ThreadPoolExecutor(
                4, 4, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        for (int i = 0; i < 20; i++) slowLane.submit(new TransferTask("TXF-" + i));
        long t0 = System.currentTimeMillis();
        long bal = fastLane.submit(new BalanceCheckTask("SAV2001")).get();
        log.info("FIXED: quick balance check returned " + bal
                + " in ~" + (System.currentTimeMillis() - t0) + "ms (fast lane)");
        slowLane.shutdownNow(); fastLane.shutdownNow();
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in TransferTask.java in a real project ───
class TransferTask implements Runnable {
    private final String id;
    TransferTask(String id) { this.id = id; }
    @Override public void run() {
        try { Thread.sleep(500); } catch (InterruptedException ignored) {} // slow downstream call
    }
}

// ─── Would be in BalanceCheckTask.java in a real project ───
class BalanceCheckTask implements Callable<Long> {
    private final String accountId;
    BalanceCheckTask(String accountId) { this.accountId = accountId; }
    @Override public Long call() {
        return 1_000_000L; // quick in-memory lookup — should return almost instantly if given a thread
    }
}

// ─── Would be in PoolInspector.java in a real project ───
class PoolInspector {
    private static final Logger log = Logger.getLogger(PoolInspector.class.getName());
    // The starvation signature: all workers active + a growing queue of waiting tasks.
    void report(String label, ThreadPoolExecutor pool) {
        log.info(String.format("%s | poolSize=%d active=%d queueDepth=%d completed=%d",
                label, pool.getPoolSize(), pool.getActiveCount(),
                pool.getQueue().size(), pool.getCompletedTaskCount()));
    }
}
